CREATE DEFINER=`root`@`localhost` PROCEDURE `AwardPoints` (IN `p_user_id` INT, IN `p_points` INT, IN `p_transaction_type` VARCHAR(20), IN `p_source` VARCHAR(50), IN `p_source_id` INT, IN `p_description` VARCHAR(255))   BEGIN
